import { FormEvent, StrictMode, useCallback, useEffect, useRef, useState } from "react";
import type { Dispatch, SetStateAction } from "react";
import { createRoot } from "react-dom/client";
import "./styles.css";

type Role = "student" | "staff";
type User = { id: string; username: string; role: Role };
type Course = { id: string; code: string; name: string };
type Member = { user: User; membershipRole: Role };
type ForumTag = { id: string; courseId: string; name: string; color: string; isDefault: boolean };
type Post = { id: string; courseId: string; tag: ForumTag; title: string; description: string; renderedDescription: string; author: User; createdAt: string; updatedAt: string };
type Comment = { id: string; postId: string; body: string; renderedBody: string; author: User; createdAt: string; updatedAt: string };
type Resource = { id: string; filename: string; downloadPath: string };
type Material = { id: string; filename: string; status: string; pageCount: number; failureMessage?: string };
type KnowledgeMap = { id: string; materialId: string; status: string; content: string; verificationMessage?: string | null; reviewedBy?: string | null; reviewedAt?: string | null; createdAt: string; updatedAt: string };
type KnowledgeMapJob = { id: string; materialId: string; status: string; failureMessage?: string | null; createdAt: string; updatedAt: string };
type MaterialMapState = { material: Material; candidate: KnowledgeMap | null; approved: KnowledgeMap | null; job: KnowledgeMapJob | null };
type Tab = "forum" | "resources" | "materials" | "members" | "settings";

async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const response = await fetch(path, { credentials: "same-origin", ...options, headers: { ...(options.body ? { "Content-Type": "application/json" } : {}), ...options.headers } });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({})) as { error?: { message?: string } };
    throw Object.assign(new Error(payload.error?.message ?? "The request could not be completed. Please try again."), { status: response.status });
  }
  return response.status === 204 ? undefined as T : response.json() as Promise<T>;
}

const date = (value: string) => new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(value));
const canDelete = (user: User, author: User) => user.id === author.id || (user.role === "staff" && author.role === "student");

function App() {
  const [user, setUser] = useState<User | null>(null); const [courses, setCourses] = useState<Course[]>([]); const [course, setCourse] = useState<Course | null>(null); const [tab, setTab] = useState<Tab>("forum"); const [notice, setNotice] = useState(""); const [error, setError] = useState(""); const [creatingCourse, setCreatingCourse] = useState(false);
  const clearMessages = () => { setError(""); setNotice(""); };
  const loadCourses = useCallback(async () => { try { const next = (await api<{ courses: Course[] }>("/api/courses")).courses; setCourses(next); setCourse(current => next.find(item => item.id === current?.id) ?? next[0] ?? null); } catch (e) { setError((e as Error).message); } }, []);
  useEffect(() => { api<{ user: User }>("/api/me").then(result => setUser(result.user)).catch(() => undefined); }, []);
  useEffect(() => { if (user) void loadCourses(); }, [user, loadCourses]);
  if (!user) return <AuthEntry onDone={setUser} />;
  const selectCourse = (next: Course) => { clearMessages(); setCourse(next); setCreatingCourse(false); setTab("forum"); };
  const signedOut = async () => { await api<void>("/api/auth/signout", { method: "POST" }).catch(() => undefined); location.reload(); };
  const created = (next: Course) => { setCourses(previous => [...previous, next].sort((a, b) => a.code.localeCompare(b.code))); setCourse(next); setCreatingCourse(false); setTab("forum"); setNotice("Course created. Add members from the Members tab."); };
  return <main className="app"><header className="topbar"><strong>University TA Help Desk</strong><span className="account"><b>{user.username}</b><span className={`badge ${user.role === "staff" ? "staff-badge" : ""}`}>{user.role}</span><button onClick={() => void signedOut()}>Sign out</button></span></header><div className="layout"><aside aria-label="Course navigation"><h2>My courses</h2>{user.role === "staff" && <button className="primary full" onClick={() => { clearMessages(); setCreatingCourse(true); }}>Create course</button>}{courses.map(item => <button className={`course ${course?.id === item.id ? "selected" : ""}`} key={item.id} onClick={() => selectCourse(item)}><b>{item.code}</b><small>{item.name}</small></button>)}{!courses.length && !creatingCourse && <p className="muted">{user.role === "staff" ? "Create a course to get started." : "You have not been added to a course yet."}</p>}</aside><section className="content">{creatingCourse ? <CourseForm onCreated={created} onCancel={() => setCreatingCourse(false)} /> : course ? <CourseWorkspace user={user} course={course} tab={tab} setTab={setTab} onCourseChange={(next) => { setCourses(items => items.map(item => item.id === next.id ? next : item)); setCourse(next); }} onCourseDeleted={(id) => { setCourses(items => items.filter(item => item.id !== id)); setCourse(items => items?.id === id ? null : items); setNotice("Course deleted."); }} error={error} notice={notice} clearMessages={clearMessages} reportError={setError} reportNotice={setNotice} /> : <EmptyDashboard role={user.role} />}</section></div></main>;
}

function CourseWorkspace({ user, course, tab, setTab, onCourseChange, onCourseDeleted, error, notice, clearMessages, reportError, reportNotice }: { user: User; course: Course; tab: Tab; setTab: (tab: Tab) => void; onCourseChange: (course: Course) => void; onCourseDeleted: (id: string) => void; error: string; notice: string; clearMessages: () => void; reportError: (message: string) => void; reportNotice: (message: string) => void }) {
  const staff = user.role === "staff"; const navigate = (next: Tab) => { clearMessages(); setTab(next); };
  return <><div className="course-heading"><p className="eyebrow">My courses / {course.code}</p><h1>{course.name}</h1><span className={`badge ${staff ? "staff-badge" : ""}`}>{staff ? "Staff access" : "Enrolled"}</span></div><nav className="tabs" aria-label="Course sections"><button className={tab === "forum" ? "active" : ""} onClick={() => navigate("forum")}>Forum</button><button className={tab === "resources" ? "active" : ""} onClick={() => navigate("resources")}>Resources</button>{staff && <><button className={tab === "materials" ? "active" : ""} onClick={() => navigate("materials")}>Knowledge Map</button><button className={tab === "members" ? "active" : ""} onClick={() => navigate("members")}>Members</button><button className={tab === "settings" ? "active" : ""} onClick={() => navigate("settings")}>Settings</button></>}</nav>{error && <Banner kind="error" message={error} onDismiss={clearMessages} />}{notice && <Banner kind="success" message={notice} onDismiss={clearMessages} />}{tab === "forum" && <Forum user={user} course={course} reportError={reportError} reportNotice={reportNotice} />}{tab === "resources" && <Resources course={course} staff={staff} reportError={reportError} reportNotice={reportNotice} />}{tab === "materials" && staff && <KnowledgeMapWorkspace course={course} reportError={reportError} reportNotice={reportNotice} />}{tab === "members" && staff && <Members course={course} reportError={reportError} reportNotice={reportNotice} />}{tab === "settings" && staff && <Settings course={course} reportError={reportError} reportNotice={reportNotice} onChanged={onCourseChange} onDeleted={onCourseDeleted} />}</>;
}

function Forum({ user, course, reportError, reportNotice }: { user: User; course: Course; reportError: (message: string) => void; reportNotice: (message: string) => void }) {
  const [posts, setPosts] = useState<Post[]>([]); const [tags, setTags] = useState<ForumTag[]>([]); const [loading, setLoading] = useState(true); const [composer, setComposer] = useState(false); const [selected, setSelected] = useState<Post | null>(null); const [activeTag, setActiveTag] = useState<string | null>(null); const [failed, setFailed] = useState(false); const requestId = useRef(0);
  const refresh = useCallback(async (filter = activeTag) => { const request = ++requestId.current; setLoading(true); setFailed(false); try { const tagResult = await api<{tags:ForumTag[]}>(`/api/courses/${course.id}/forum-tags`); if(request!==requestId.current)return; setTags(tagResult.tags); if (filter && !tagResult.tags.some(tag => tag.id === filter)) { setActiveTag(null); reportNotice("That tag was removed. Showing all posts."); filter = null; } const query = filter ? `?tagId=${encodeURIComponent(filter)}` : ""; const result=await api<{posts:Post[]}>(`/api/courses/${course.id}/posts${query}`); if(request===requestId.current)setPosts(result.posts); } catch (e) { if(request===requestId.current){setPosts([]);setTags([]);setSelected(null);setComposer(false);setFailed(true);reportError((e as Error).message);} } finally { if(request===requestId.current)setLoading(false); } }, [course.id, activeTag, reportError, reportNotice]);
  useEffect(() => { setSelected(null); setComposer(false); setActiveTag(null); void refresh(null); }, [course.id]);
  const filterBy = (id:string) => { const next=activeTag===id?null:id; setActiveTag(next); void refresh(next); };
  if (selected) return <Thread user={user} course={course} post={selected} back={() => { setSelected(null); void refresh(); }} onDeleted={postId => { setPosts(items => items.filter(item => item.id !== postId)); setSelected(null); reportNotice("Post deleted."); }} reportError={reportError} reportNotice={reportNotice} />;
  return <div><div className="section-heading"><div><h2>Forum</h2><p className="muted">Discuss course questions with your classmates and course staff.</p></div><button className="primary" onClick={() => setComposer(true)}>New post</button></div><div className="tag-filter" role="group" aria-label="Filter by tag">{loading && !tags.length ? <p className="loading">Loading tags…</p> : tags.map(tag=><button key={tag.id} className={`tag-pill ${activeTag===tag.id?"selected":""}`} style={{"--tag-color":tag.color} as React.CSSProperties} aria-pressed={activeTag===tag.id} onClick={()=>filterBy(tag.id)}>{activeTag===tag.id&&<span aria-hidden="true">✓ </span>}{tag.name}</button>)}</div>{composer && <PostEditor course={course} onSaved={(post) => { setComposer(false); if(!activeTag||post.tag.id===activeTag)setPosts(items => [post, ...items]);else void refresh(); reportNotice("Post published."); }} onCancel={() => setComposer(false)} reportError={reportError} />}{loading ? <p className="loading">Loading forum…</p> : failed ? <EmptyState title="Forum unavailable" text="Your course access may have changed. Try again to refresh access." action="Retry" onAction={() => void refresh()} /> : posts.length ? <div className="cards">{posts.map(post => <article className="post-card" key={post.id}><button className="post-link" onClick={() => setSelected(post)}><h3>{post.title}</h3><p className="post-preview-meta"><span className="post-preview-tag" style={{color:post.tag.color}}>{post.tag.name}</span><span>{post.author.username}{post.author.role === "staff" && <StaffAuthorBadge />}</span><span>{date(post.createdAt)}</span></p><div className="markdown" dangerouslySetInnerHTML={{ __html: post.renderedDescription }} /></button></article>)}</div> : activeTag ? <EmptyState title={`No posts tagged “${tags.find(tag=>tag.id===activeTag)?.name ?? ""}”.`} text="Try another tag or show all course posts." action="Clear tag filter" onAction={()=>filterBy(activeTag)} /> : <EmptyState title="No posts yet" text="Start the course discussion by asking the first question." />}</div>;
}
function TagBadge({tag}:{tag:ForumTag}) { return <span className="tag-pill tag-badge" style={{"--tag-color":tag.color} as React.CSSProperties}>{tag.name}</span>; }
function StaffAuthorBadge() { return <span className="badge staff-badge staff-author-badge">STAFF</span>; }

function Thread({ user, course, post: initialPost, back, onDeleted, reportError, reportNotice }: { user: User; course: Course; post: Post; back: () => void; onDeleted: (postId: string) => void; reportError: (message: string) => void; reportNotice: (message: string) => void }) {
  const [post, setPost] = useState<Post | null>(initialPost); const [comments, setComments] = useState<Comment[]>([]); const [loading, setLoading] = useState(true); const [failed, setFailed] = useState(false); const [editingPost, setEditingPost] = useState(false); const [reply, setReply] = useState(""); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { setLoading(true); setFailed(false); try { const result = await api<{ post: Post; comments: Comment[] }>(`/api/courses/${course.id}/posts/${initialPost.id}`); setPost(result.post); setComments(result.comments); } catch (e) { setPost(null); setComments([]); setEditingPost(false); setFailed(true); reportError((e as Error).message); } finally { setLoading(false); } }, [course.id, initialPost.id, reportError]);
  useEffect(() => { void load(); }, [load]);
  const submitReply = async (event: FormEvent) => { event.preventDefault(); if (!post || !reply.trim()) return reportError("Reply text is required."); setBusy(true); try { const result = await api<{ comment: Comment }>(`/api/courses/${course.id}/posts/${post.id}/comments`, { method: "POST", body: JSON.stringify({ body: reply }) }); setComments(items => [...items, result.comment]); setReply(""); reportNotice("Reply published."); } catch (e) { reportError((e as Error).message); void load(); } finally { setBusy(false); } };
  if (!post) return <div><button className="back" onClick={back}>← Back to forum</button>{loading ? <p className="loading">Loading discussion…</p> : <EmptyState title="Discussion unavailable" text="This discussion may have been removed or your course access changed." action="Retry" onAction={() => void load()} />}</div>;
  return <div><button className="back" onClick={back}>← Back to forum</button>{editingPost ? <PostEditor course={course} post={post} onSaved={(next) => { setPost(next); setEditingPost(false); reportNotice("Post updated."); }} onCancel={() => setEditingPost(false)} reportError={reportError} /> : <article className="thread"><div className="section-heading"><div><h2>{post.title}</h2><p className="post-preview-meta"><span className="post-preview-tag" style={{color:post.tag.color}}>{post.tag.name}</span><span>{post.author.username}{post.author.role === "staff" && <StaffAuthorBadge />}</span><span>{date(post.createdAt)}</span></p></div><div className="actions">{user.id === post.author.id && <button onClick={() => setEditingPost(true)}>Edit post</button>}{canDelete(user, post.author) && <DeleteButton label="post" action={async () => { await api(`/api/courses/${course.id}/posts/${post.id}`, { method: "DELETE" }); onDeleted(post.id); }} reportError={reportError} onFailure={() => void load()} />}</div></div><div className="markdown" dangerouslySetInnerHTML={{ __html: post.renderedDescription }} /></article>}<section className="replies"><h2>Replies</h2>{loading ? <p className="loading">Loading replies…</p> : comments.length ? comments.map(comment => <CommentCard key={comment.id} user={user} course={course} postId={post.id} comment={comment} onChanged={setComments} reload={() => void load()} reportError={reportError} reportNotice={reportNotice} />) : <p className="muted no-replies">No replies yet. Add a helpful response below.</p>}<form className="editor reply" onSubmit={submitReply}><label htmlFor="reply">Write a response</label><textarea id="reply" value={reply} onChange={event => setReply(event.target.value)} disabled={busy} required /><p className="muted">Markdown is supported. Submitted text is safely rendered.</p><button className="primary" disabled={busy}>{busy ? "Posting…" : "Post reply"}</button></form></section></div>;
}

const trimTagWhitespace=(value:string)=>value.replace(/^[\p{White_Space}\uFEFF]+|[\p{White_Space}\uFEFF]+$/gu, "");
const TAG_PALETTE = [{name:"Blue",color:"#1D4ED8"},{name:"Green",color:"#166534"},{name:"Amber",color:"#854D0E"},{name:"Violet",color:"#6D28D9"},{name:"Teal",color:"#0F766E"},{name:"Red",color:"#B91C1C"},{name:"Light Blue",color:"#0369A1"},{name:"Magenta",color:"#A21CAF"},{name:"Charcoal",color:"#1F2937"}];
const tagColorName=(tag:ForumTag)=>tag.isDefault?"Grey":(TAG_PALETTE.find(item=>item.color===tag.color)?.name??"Color");
function PostEditor({ course, post, onSaved, onCancel, reportError }: { course: Course; post?: Post; onSaved: (post: Post) => void; onCancel: () => void; reportError: (message: string) => void }) {
  const [title, setTitle] = useState(post?.title ?? ""); const [description, setDescription] = useState(post?.description ?? ""); const [tags,setTags]=useState<ForumTag[]>([]); const [tagId,setTagId]=useState(post?.tag.id??""); const tagIdRef=useRef(tagId); const [loading,setLoading]=useState(true); const [busy, setBusy] = useState(false); const [error,setError]=useState("");
  useEffect(()=>{tagIdRef.current=tagId;},[tagId]);
  const loadTags=useCallback(async()=>{setLoading(true);setError("");try{const current=(await api<{tags:ForumTag[]}>(`/api/courses/${course.id}/forum-tags`)).tags;setTags(current);if(!current.some(tag=>tag.id===tagIdRef.current)){const general=current.find(tag=>tag.isDefault);const nextId=general?.id??"";tagIdRef.current=nextId;setTagId(nextId);if(post) setError("The previous tag was removed. General is selected.");}}catch(e){setTags([]);tagIdRef.current="";setTagId("");setError((e as Error).message);}finally{setLoading(false);}},[course.id,post?.id]);
  useEffect(()=>{void loadTags();},[loadTags]);
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!title.trim()) return reportError("A post title is required."); if (title.length > 120) return reportError("Post title must be at most 120 characters."); if (description.length > 2000) return reportError("Description must be at most 2,000 characters."); if(!tagId||!tags.some(tag=>tag.id===tagId))return reportError("Choose a current tag for this course."); setBusy(true); try { const result = await api<{ post: Post }>(post ? `/api/courses/${course.id}/posts/${post.id}` : `/api/courses/${course.id}/posts`, { method: post ? "PATCH" : "POST", body: JSON.stringify({ title, description, tagId }) }); onSaved(result.post); } catch (e) { reportError((e as Error).message); await loadTags(); } finally { setBusy(false); } };
  return <form className="editor post-editor" onSubmit={submit}><h2>{post ? "Edit post" : "Create a post"}</h2><label htmlFor="post-title">Title <small>{title.length}/120</small></label><input id="post-title" maxLength={120} value={title} onChange={event => setTitle(event.target.value)} disabled={busy} required /><fieldset className="post-tag-fieldset" disabled={busy||!tags.length}><legend>Tag</legend>{loading?<p className="loading">Loading course tags…</p>:<div className="post-tag-picker" role="radiogroup" aria-label="Tag">{tags.map((tag,index)=><button key={tag.id} type="button" role="radio" aria-checked={tagId===tag.id} tabIndex={tagId===tag.id?0:-1} className="tag-pill" style={{"--tag-color":tag.color} as React.CSSProperties} onClick={()=>setTagId(tag.id)} onKeyDown={event=>{const buttons=Array.from(event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>('button[role="radio"]')??[]);let nextIndex=-1;if(event.key==="ArrowRight"||event.key==="ArrowDown")nextIndex=(index+1)%tags.length;else if(event.key==="ArrowLeft"||event.key==="ArrowUp")nextIndex=(index-1+tags.length)%tags.length;else if(event.key==="Home")nextIndex=0;else if(event.key==="End")nextIndex=tags.length-1;if(nextIndex>=0){event.preventDefault();setTagId(tags[nextIndex].id);buttons[nextIndex]?.focus();}}}>{tag.name}</button>)}</div>}</fieldset>{error&&<p role="status" className="muted">{error} {!tags.length&&<button type="button" onClick={()=>void loadTags()}>Retry</button>}</p>}<label htmlFor="post-description">Description <small>{description.length}/2000</small></label><textarea id="post-description" maxLength={2000} value={description} onChange={event => setDescription(event.target.value)} disabled={busy} /><p className="muted">Markdown is supported. HTML is not executed.</p><div className="actions"><button type="button" onClick={onCancel} disabled={busy}>Cancel</button><button className="primary" disabled={busy||loading||!tags.some(tag=>tag.id===tagId)}>{busy ? "Saving…" : post ? "Save changes" : "Publish post"}</button></div></form>;
}

function CommentCard({ user, course, postId, comment, onChanged, reload, reportError, reportNotice }: { user: User; course: Course; postId: string; comment: Comment; onChanged: Dispatch<SetStateAction<Comment[]>>; reload: () => void; reportError: (message: string) => void; reportNotice: (message: string) => void }) {
  const [editing, setEditing] = useState(false); const [body, setBody] = useState(comment.body); const [busy, setBusy] = useState(false);
  const save = async (event: FormEvent) => { event.preventDefault(); if (!body.trim()) return reportError("Reply text is required."); setBusy(true); try { const result = await api<{ comment: Comment }>(`/api/courses/${course.id}/posts/${postId}/comments/${comment.id}`, { method: "PATCH", body: JSON.stringify({ body }) }); onChanged(items => items.map(item => item.id === comment.id ? result.comment : item)); setEditing(false); reportNotice("Reply updated."); } catch (e) { reportError((e as Error).message); } finally { setBusy(false); } };
  return <article className="comment"><p className="meta"><b>{comment.author.username}</b>{comment.author.role === "staff" ? <StaffAuthorBadge /> : " · student"} · {date(comment.createdAt)}</p>{editing ? <form onSubmit={save}><textarea value={body} onChange={event => setBody(event.target.value)} disabled={busy} required /><div className="actions"><button type="button" onClick={() => { setBody(comment.body); setEditing(false); }} disabled={busy}>Cancel</button><button className="primary" disabled={busy}>Save reply</button></div></form> : <><div className="markdown" dangerouslySetInnerHTML={{ __html: comment.renderedBody }} />{canDelete(user, comment.author) && <div className="card-actions">{user.id === comment.author.id && <button onClick={() => setEditing(true)}>Edit</button>}<DeleteButton label="reply" action={async () => { await api(`/api/courses/${course.id}/posts/${postId}/comments/${comment.id}`, { method: "DELETE" }); onChanged(items => items.filter(item => item.id !== comment.id)); reportNotice("Reply deleted."); }} reportError={reportError} onFailure={reload} /></div>}</>}</article>;
}

function Members({ course, reportError, reportNotice }: { course: Course; reportError: (message: string) => void; reportNotice: (message: string) => void }) {
  const [members, setMembers] = useState<Member[]>([]); const [username, setUsername] = useState(""); const [loading, setLoading] = useState(true); const [failed, setFailed] = useState(false); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { setLoading(true); setFailed(false); try { setMembers((await api<{ members: Member[] }>(`/api/courses/${course.id}/members`)).members); } catch (e) { setMembers([]); setFailed(true); reportError((e as Error).message); } finally { setLoading(false); } }, [course.id, reportError]);
  useEffect(() => { void load(); }, [load]);
  const add = async (event: FormEvent) => { event.preventDefault(); if (!username.trim()) return reportError("Enter an existing username."); setBusy(true); try { await api(`/api/courses/${course.id}/members`, { method: "POST", body: JSON.stringify({ username }) }); setUsername(""); await load(); reportNotice("Member added."); } catch (e) { reportError((e as Error).message); } finally { setBusy(false); } };
  const remove = async (member: Member) => { if (!confirm(`Remove ${member.user.username} from this course? Their course-forum access will end immediately.`)) return; try { await api(`/api/courses/${course.id}/members/${member.user.id}`, { method: "DELETE" }); await load(); reportNotice("Student removed from the course."); } catch (e) { reportError((e as Error).message); await load(); } };
  const staff = members.filter(member => member.membershipRole === "staff"); const students = members.filter(member => member.membershipRole === "student");
  return <div><h2>Members</h2><p className="muted">Add an existing account by username. Students cannot enrol or withdraw themselves.</p><form className="inline-form" onSubmit={add}><label htmlFor="member-username">Username</label><input id="member-username" value={username} onChange={event => setUsername(event.target.value)} disabled={busy || failed} required /><button className="primary" disabled={busy || failed}>{busy ? "Adding…" : "Add member"}</button></form>{loading ? <p className="loading">Loading members…</p> : failed ? <EmptyState title="Members unavailable" text="Your staff access may have changed. Try again to refresh access." action="Retry" onAction={() => void load()} /> : <div className="member-columns"><MemberList title="Course staff" members={staff} /><MemberList title="Students" members={students} onRemove={remove} /></div>}</div>;
}
function MemberList({ title, members, onRemove }: { title: string; members: Member[]; onRemove?: (member: Member) => void }) { return <section><h3>{title}</h3>{members.length ? <ul className="rows">{members.map(member => <li key={member.user.id}><span><b>{member.user.username}</b></span>{onRemove && <button className="danger" onClick={() => onRemove(member)}>Remove</button>}</li>)}</ul> : <p className="muted">No {title.toLowerCase()} yet.</p>}</section>; }

function Settings({ course, reportError, reportNotice, onChanged, onDeleted }: { course: Course; reportError: (message: string) => void; reportNotice: (message: string) => void; onChanged: (course: Course) => void; onDeleted: (id: string) => void }) { const [name, setName] = useState(course.name); const [busy, setBusy] = useState(false); const rename = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const result = await api<{ course: Course }>(`/api/courses/${course.id}`, { method: "PATCH", body: JSON.stringify({ name }) }); onChanged(result.course); reportNotice("Course name updated."); } catch (e) { reportError((e as Error).message); } finally { setBusy(false); } }; const remove = async () => { if (!confirm(`Delete ${course.code} permanently? Its forum posts, replies, memberships, and resources will no longer be accessible.`)) return; setBusy(true); try { await api(`/api/courses/${course.id}`, { method: "DELETE" }); onDeleted(course.id); } catch (e) { reportError((e as Error).message); setBusy(false); } }; return <div><h2>Course settings</h2><form className="editor narrow settings-course-details" onSubmit={rename}><label htmlFor="course-name">Course name</label><input id="course-name" value={name} onChange={event => setName(event.target.value)} disabled={busy} required /><button className="primary" disabled={busy}>{busy ? "Saving…" : "Save name"}</button></form><ForumTagsSettings course={course} reportError={reportError} reportNotice={reportNotice} /><section className="danger-zone"><h3>Delete course</h3><p>This permanently removes the course and makes its forum data unavailable.</p><button className="danger" onClick={() => void remove()} disabled={busy}>Delete course</button></section></div>; }
function ForumTagsSettings({course,reportError,reportNotice}:{course:Course;reportError:(m:string)=>void;reportNotice:(m:string)=>void}) {
 const [tags,setTags]=useState<ForumTag[]>([]),[loading,setLoading]=useState(true),[failed,setFailed]=useState(false),[name,setName]=useState(""),[color,setColor]=useState(TAG_PALETTE[0].color),[editing,setEditing]=useState<string|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState("");
 const load=useCallback(async()=>{setLoading(true);setFailed(false);try{setTags((await api<{tags:ForumTag[]}>(`/api/courses/${course.id}/forum-tags`)).tags);}catch(e){setFailed(true);reportError((e as Error).message);}finally{setLoading(false);}},[course.id,reportError]);useEffect(()=>{void load();},[load]);
 const save=async(e:FormEvent)=>{e.preventDefault();setError("");setBusy(true);try{const trimmedName=trimTagWhitespace(name);if(!trimmedName){setError("Tag name is required.");setBusy(false);return;}const data={name:trimmedName,color};if(editing){await api(`/api/courses/${course.id}/forum-tags/${editing}`,{method:"PATCH",body:JSON.stringify(data)});reportNotice("Forum tag updated.");}else{await api(`/api/courses/${course.id}/forum-tags`,{method:"POST",body:JSON.stringify(data)});reportNotice("Forum tag added.");}setName("");setEditing(null);await load();}catch(ex){setError((ex as Error).message);}finally{setBusy(false);}};
 const startEdit=(tag:ForumTag)=>{setEditing(tag.id);setName(tag.name);setColor(tag.color);setError("");};const remove=async(tag:ForumTag)=>{if(!confirm(`Delete “${tag.name}”? Posts using it will move to General.`))return;setBusy(true);try{await api(`/api/courses/${course.id}/forum-tags/${tag.id}`,{method:"DELETE"});await load();reportNotice(`“${tag.name}” was deleted. Its posts now use General.`);}catch(e){reportError((e as Error).message);}finally{setBusy(false);}};
 return <section className="forum-tag-settings"><h3>Forum tags</h3><p>Up to 7 tags per course, including General (the default tag)</p>{loading?<p className="loading">Loading forum tags…</p>:failed?<EmptyState title="Forum tags unavailable" text="Try again to load course tags." action="Retry" onAction={()=>void load()} />:<><ul className="rows">{tags.map(tag=><li key={tag.id}><span><TagBadge tag={tag} /> </span>{!tag.isDefault&&<span className="card-actions"><button onClick={()=>startEdit(tag)}>Edit</button><button className="danger" onClick={()=>void remove(tag)} disabled={busy}>Delete</button></span>}</li>)}</ul>{(tags.length<7||editing)&&<form className="editor tag-editor" onSubmit={save}><h4>{editing?"Edit tag":"Add tag"}</h4><label htmlFor="tag-name">Tag name <small>{[...name].length}/20</small></label><input id="tag-name" maxLength={40} value={name} onChange={e=>setName(e.target.value)} disabled={busy} required /><fieldset><legend>Color</legend><div className="swatch-grid" role="radiogroup" aria-label="Tag color">{TAG_PALETTE.map(swatch=><button type="button" role="radio" aria-checked={color===swatch.color} aria-label={swatch.name} tabIndex={color===swatch.color?0:-1} className={`swatch ${color===swatch.color?"chosen":""}`} style={{"--tag-color":swatch.color} as React.CSSProperties} onKeyDown={event=>{const buttons=Array.from(event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>("button")??[]);const index=buttons.indexOf(event.currentTarget);let nextIndex=-1;if(event.key==="ArrowRight"||event.key==="ArrowDown")nextIndex=(index+1)%buttons.length;else if(event.key==="ArrowLeft"||event.key==="ArrowUp")nextIndex=(index-1+buttons.length)%buttons.length;else if(event.key==="Home")nextIndex=0;else if(event.key==="End")nextIndex=buttons.length-1;if(nextIndex>=0){event.preventDefault();const next=buttons[nextIndex];const colorValue=next.getAttribute("data-color");if(colorValue)setColor(colorValue);next.focus();}}} data-color={swatch.color} onClick={()=>setColor(swatch.color)} disabled={busy}>{color===swatch.color?"✓":""}</button>)}</div></fieldset>{error&&<p role="alert" className="job-failure">{error}</p>}<div className="actions">{editing&&<button type="button" onClick={()=>{setEditing(null);setName("");setError("");}}>Cancel</button>}<button className="primary" disabled={busy||(tags.length>=7&&!editing)}>{busy?(editing?"Saving…":"Adding…"):editing?"Save tag":"Add tag"}</button></div></form>}{tags.length>=7&&<p role="status">The tag limit has been reached.</p>}</>}</section>;
}

function Resources({ course, staff, reportError, reportNotice }: { course: Course; staff: boolean; reportError: (message: string) => void; reportNotice: (message: string) => void }) { const [resources, setResources] = useState<Resource[]>([]); const [loading, setLoading] = useState(true); const [uploadOpen, setUploadOpen] = useState(false); const closeUpload = useCallback(() => setUploadOpen(false), []); const refresh = useCallback(async () => { setLoading(true); try { setResources((await api<{ resources: Resource[] }>(`/api/courses/${course.id}/resources`)).resources); } catch (e) { reportError((e as Error).message); } finally { setLoading(false); } }, [course.id, reportError]); useEffect(() => { void refresh(); }, [refresh]); const remove = async (resource: Resource) => { if (!confirm(`Delete ${resource.filename}? This immediately removes it from Resources and new AI requests. This cannot be undone.`)) return; try { await api(`/api/courses/${course.id}/materials/${resource.id}`, { method: "DELETE" }); await refresh(); reportNotice(`${resource.filename} was deleted.`); } catch (e) { reportError((e as Error).message); } }; return <div><div className="section-heading"><div><h2>Resources</h2><p className="muted">Course PDFs shared by staff.</p></div>{staff && <button className="primary" onClick={() => setUploadOpen(true)}>Upload file</button>}</div>{loading ? <p className="loading">Loading resources…</p> : resources.length ? <ul className="rows">{resources.map(resource => <li key={resource.id}><span>📄 {resource.filename}</span><span className="card-actions"><a href={resource.downloadPath}>Download PDF</a>{staff && <button className="danger" aria-label={`Delete ${resource.filename}`} onClick={() => void remove(resource)}>Delete file</button>}</span></li>)}</ul> : <EmptyState title="No resources have been shared yet" text="Check back after course staff upload a PDF." />}{uploadOpen && <UploadDialog course={course} onClose={closeUpload} onUploaded={async filename => { closeUpload(); reportNotice(`${filename} was accepted and is processing.`); await refresh(); }} />}</div>; }
function UploadDialog({ course, onClose, onUploaded }: { course: Course; onClose: () => void; onUploaded: (filename: string) => void }) { const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const dialog = useRef<HTMLElement>(null); const opener = useRef<HTMLElement | null>(document.activeElement as HTMLElement | null); const input = useRef<HTMLInputElement>(null); useEffect(() => { input.current?.focus(); const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); onClose(); } if (event.key === "Tab" && dialog.current) { const items = [...dialog.current.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled)')]; if (!items.length) return; const first = items[0], last = items[items.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } } }; document.addEventListener("keydown", onKey); return () => { document.removeEventListener("keydown", onKey); opener.current?.focus(); }; }, [onClose]); const upload = async (event: FormEvent) => { event.preventDefault(); setError(""); if (!file) return setError("Choose a PDF to upload."); if (file.type !== "application/pdf") return setError("This file cannot be used. Upload an unprotected, valid PDF."); setBusy(true); try { const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ""; bytes.forEach(byte => binary += String.fromCharCode(byte)); await api(`/api/courses/${course.id}/materials`, { method: "POST", body: JSON.stringify({ filename: file.name, contentType: file.type, contentBase64: btoa(binary) }) }); onUploaded(file.name); } catch (e) { setError((e as Error).message || "The PDF was not uploaded. Check your connection and try again."); } finally { setBusy(false); } }; return <div className="modal-backdrop" onMouseDown={event => { if (!busy && event.target === event.currentTarget) onClose(); }}><section className="upload-dialog" role="dialog" aria-modal="true" aria-labelledby="upload-title" ref={dialog}><div className="section-heading"><h2 id="upload-title">Upload course PDF</h2><button type="button" aria-label="Close upload dialog" onClick={onClose} disabled={busy}>Close</button></div><form className="editor" onSubmit={event => void upload(event)}><PdfCompatibilityNotice /><label htmlFor="upload-pdf">Choose PDF</label><input ref={input} id="upload-pdf" type="file" accept="application/pdf,.pdf" onChange={event => setFile(event.target.files?.[0] ?? null)} disabled={busy} />{file && <div><span>{file.name} · {(file.size / (1024 * 1024)).toFixed(2)} MB</span> <button type="button" onClick={() => setFile(null)} disabled={busy}>Remove selection</button></div>}<small>PDF only · maximum 20 MB · maximum 100 pages · up to 20 active PDFs per course.</small>{error && <p role="alert" className="job-failure">{error}</p>}<div className="actions"><button type="button" onClick={onClose} disabled={busy}>Cancel</button><button className="primary" disabled={!file || busy}>{busy ? "Uploading…" : "Upload PDF"}</button></div></form></section></div>; }
function KnowledgeMapWorkspace({ course, reportError, reportNotice }: { course: Course; reportError: (message: string) => void; reportNotice: (message: string) => void }) {
  const [maps, setMaps] = useState<MaterialMapState[]>([]); const [fallbackConfigured, setFallbackConfigured] = useState(false); const [loading, setLoading] = useState(true); const [mapBusy, setMapBusy] = useState<string | null>(null);
  const load = useCallback(async () => { try { const mapResult = await api<{ maps: MaterialMapState[]; fallbackConfigured: boolean }>(`/api/courses/${course.id}/knowledge-maps`); setMaps(mapResult.maps); setFallbackConfigured(mapResult.fallbackConfigured); } catch (e) { reportError((e as Error).message); } finally { setLoading(false); } }, [course.id, reportError]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (!maps.some(state => state.job?.status === "queued" || state.job?.status === "generating")) return; const timer = window.setInterval(() => void load(), 1800); return () => window.clearInterval(timer); }, [maps, load]);
  const generate = async (materialId?: string) => { const active = maps.filter(state => state.material.status === "active"); if (!active.length) return reportError("Upload and process at least one text-ready PDF before generating a Knowledge Map."); const label = materialId ? maps.find(state => state.material.id === materialId)?.material.filename : `${active.length} eligible PDFs`; if (!confirm(`Generate separate Knowledge Map request${materialId ? "" : "s"} for ${label}? Existing approved and pending maps stay visible if an attempt fails.`)) return; setMapBusy(materialId ?? "all"); try { await api(materialId ? `/api/courses/${course.id}/materials/${materialId}/knowledge-map/generate` : `/api/courses/${course.id}/knowledge-maps/generate-all`, { method: "POST" }); await load(); reportNotice("Knowledge Map generation queued. Each PDF updates independently."); } catch (e) { reportError((e as Error).message); } finally { setMapBusy(null); } };
  const review = async (materialId: string, decision: "approve" | "reject") => { const approved = decision === "approve"; if (!confirm(approved ? "Approve this PDF's map for future student AI navigation? Student answers must still cite the original PDF and pages." : "Reject this unapproved generated map? This removes only the candidate; any approved map stays unchanged.")) return; setMapBusy(materialId); try { await api(`/api/courses/${course.id}/materials/${materialId}/knowledge-map/${decision}`, { method: "POST" }); await load(); reportNotice(approved ? "Knowledge Map approved for student AI navigation." : "Generated candidate rejected."); } catch (e) { reportError((e as Error).message); } finally { setMapBusy(null); } };
  return <KnowledgeMapsByPdf course={course} maps={maps} busy={mapBusy} fallbackConfigured={fallbackConfigured} loading={loading} onGenerate={id => void generate(id)} onReview={(id, decision) => void review(id, decision)} onRefresh={() => void load()} />;
}

function PdfCompatibilityNotice() { return <aside className="pdf-compatibility" aria-label="PDF compatibility information"><b>ⓘ PDF compatibility</b><p>For Knowledge Maps and future AI help, choose a PDF with selectable text. Standard PDFs exported from PowerPoint, Word, or lecture-note tools are supported, including compressed text PDFs.</p><p>Scanned or image-only PDFs can be shared in Resources but cannot yet be used for text-grounded AI help.</p></aside>; }
function materialStatusDetail(material: Material) { if (material.status === "processing") return "Checking this PDF for page-aware text."; if (material.status === "active") return "Ready for Knowledge Maps and future AI help."; if (material.status === "resource_only") return "No selectable text was found. Students can download it, but it cannot support AI help yet."; return material.failureMessage ?? "This PDF could not be processed. It may be malformed, encrypted, password-protected, or too complex to process."; }
function MaterialStatusBadge({ status }: { status: string }) { const label = status === "processing" ? "Processing text" : status === "active" ? "Text ready" : status === "resource_only" ? "Resource only" : status === "failed" ? "Text extraction failed" : status.replaceAll("_", " "); return <span className={`status-badge ${status}`}>{label}</span>; }

function KnowledgeMapsByPdf({ course, maps, busy, fallbackConfigured, loading, onGenerate, onReview, onRefresh }: { course: Course; maps: MaterialMapState[]; busy: string | null; fallbackConfigured: boolean; loading: boolean; onGenerate: (id?: string) => void; onReview: (id: string, decision: "approve" | "reject") => void; onRefresh: () => void }) {
  const eligible = maps.filter(state => state.material.status === "active");
  return <section className="knowledge-map" aria-labelledby="knowledge-map-heading"><div className="section-heading"><div><h2 id="knowledge-map-heading">Course Knowledge Map</h2><p className="muted">The Course Knowledge Map organizes course topics to help student AI search for relevant material and find supporting PDF pages. It guides retrieval but does not replace the original PDFs: student answers still cite those sources, and staff must review and approve a map before it can be used.</p>{fallbackConfigured && <p className="muted">Generation uses Gemma 4 26B. If it has a temporary service failure, the system tries Qwen 3.5 9B once before reporting a failure.</p>}</div><div className="actions"><button onClick={onRefresh}>Refresh map status</button><button className="primary" onClick={() => onGenerate()} disabled={busy !== null || !eligible.length}>Generate all eligible maps</button></div></div>{loading ? <p className="loading">Loading Knowledge Map…</p> : maps.length ? maps.map(state => <MaterialMap key={state.material.id} course={course} state={state} busy={busy === state.material.id || busy === "all"} onGenerate={() => onGenerate(state.material.id)} onReview={decision => onReview(state.material.id, decision)} />) : <EmptyState title="No course PDFs yet" text="Upload a text-ready PDF from Resources to generate the course Knowledge Map." />}</section>;
}
function MaterialMap({ course: _course, state, busy, onGenerate, onReview }: { course: Course; state: MaterialMapState; busy: boolean; onGenerate: () => void; onReview: (decision: "approve" | "reject") => void }) {
  const { material, candidate, approved, job } = state; const running = job?.status === "queued" || job?.status === "generating";
  return <article className="map-panel"><div className="section-heading"><div><h3>{material.filename}</h3><p className="meta"><MaterialStatusBadge status={material.status} /> {job && <> · <StatusBadge status={job.status} /></>}</p></div>{material.status === "active" && <button onClick={onGenerate} disabled={busy || running}>{candidate || approved ? "Update map" : "Generate map"}</button>}</div>{material.status !== "active" && <p className="muted">Skipped: {materialStatusDetail(material)}</p>}{running && <p role="status">Generating this PDF’s map. Existing maps remain available.</p>}{job?.status === "failed" && <div className="job-failure" role="alert"><b>Map generation unavailable</b><p>{job.failureMessage}</p></div>}{approved && <section><h4>Approved for student AI navigation</h4><div className="map-content" role="region" aria-label={`Approved Knowledge Map content for ${material.filename}`} tabIndex={0}>{approved.content}</div><p className="muted">Approved {approved.reviewedAt && date(approved.reviewedAt)}.</p></section>}{candidate && <section><h4>AI-generated — staff review required</h4>{candidate.verificationMessage && <div className="job-failure" role="alert"><b>Unverified Knowledge Map — staff review only</b><p>{candidate.verificationMessage}</p></div>}<div className="map-content" role="region" aria-label={`Knowledge Map content for ${material.filename}`} tabIndex={0}>{candidate.content}</div><div className="actions">{!candidate.verificationMessage && <button className="primary" onClick={() => onReview("approve")} disabled={busy}>Approve for student AI navigation</button>}<button className="danger" onClick={() => onReview("reject")} disabled={busy}>Reject</button></div></section>}</article>;
}

function StatusBadge({ status }: { status: string }) { return <span className={`status-badge ${status}`}>{status.replaceAll("_", " ")}</span>; }
function CourseForm({ onCreated, onCancel }: { onCreated: (course: Course) => void; onCancel: () => void }) { const [code, setCode] = useState(""); const [name, setName] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { onCreated((await api<{ course: Course }>("/api/courses", { method: "POST", body: JSON.stringify({ code, name }) })).course); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }; return <form className="editor narrow" onSubmit={submit}><h1>Create course</h1><p className="muted">You will become its first course staff member.</p><label>Course code <input value={code} maxLength={32} onChange={event => setCode(event.target.value)} disabled={busy} required /></label><label>Course name <input value={name} maxLength={160} onChange={event => setName(event.target.value)} disabled={busy} required /></label>{error && <Banner kind="error" message={error} />}<div className="actions"><button type="button" onClick={onCancel} disabled={busy}>Cancel</button><button className="primary" disabled={busy}>{busy ? "Creating…" : "Create course"}</button></div></form>; }
function AuthEntry({ onDone }: { onDone: (user: User) => void }) { const [role, setRole] = useState<Role | null>(null); if (!role) return <main className="auth"><h1>University TA Help Desk</h1><p>Choose your role to continue.</p><div className="choice-actions"><button className="role-card" onClick={() => setRole("student")}><b>Student</b><span>Access your enrolled course forums</span></button><button className="role-card" onClick={() => setRole("staff")}><b>Staff</b><span>Manage courses and participate in forums</span></button></div></main>; return <RoleAccess role={role} onDone={onDone} back={() => setRole(null)} />; }
function RoleAccess({ role, onDone, back }: { role: Role; onDone: (user: User) => void; back: () => void }) { const [mode, setMode] = useState<"choose" | "signin" | "signup">("choose"); const [username, setUsername] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { const result = await api<{ user: User }>(mode === "signup" ? "/api/auth/signup" : "/api/auth/signin", { method: "POST", body: JSON.stringify(mode === "signup" ? { username, password, role } : { username, password }) }); if (result.user.role !== role) throw new Error(`This is not a ${role} account.`); onDone(result.user); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }; if (mode === "choose") return <main className="auth"><h1>{role === "student" ? "Student access" : "Staff access"}</h1><p>{role === "student" ? "Sign in or create a student account to access forums where course staff add you." : "Choose how you would like to continue."}</p><div className="choice-actions"><button className="primary" onClick={() => setMode("signin")}>Log in</button><button onClick={() => setMode("signup")}>Create {role} account</button></div><button className="back-to-role" style={{ marginTop: "1.5rem" }} onClick={back}>← Back to role selection</button></main>; return <main className="auth"><h1>{mode === "signup" ? `Create ${role} account` : `${role} log in`}</h1>{role === "staff" && mode === "signup" && <p className="notice">For this test project, staff accounts are self-selected and are not institutionally verified.</p>}<form onSubmit={submit}><label>Username<input autoComplete="username" value={username} onChange={event => setUsername(event.target.value)} disabled={busy} required /></label><label>Password<input type="password" autoComplete={mode === "signup" ? "new-password" : "current-password"} value={password} onChange={event => setPassword(event.target.value)} disabled={busy} required /></label>{error && <Banner kind="error" message={error} />}<button className="primary" disabled={busy}>{busy ? "Please wait…" : mode === "signup" ? "Create account" : "Log in"}</button><button type="button" onClick={() => { setError(""); setMode("choose"); }} disabled={busy}>Back</button></form></main>; }
function DeleteButton({ label, action, reportError, onFailure }: { label: string; action: () => Promise<void>; reportError: (message: string) => void; onFailure?: () => void }) { const remove = async () => { if (!confirm(`Delete this ${label}? This cannot be undone.`)) return; try { await action(); } catch (e) { reportError((e as Error).message); onFailure?.(); } }; return <button className="danger" onClick={() => void remove()}>Delete</button>; }
function Banner({ kind, message, onDismiss }: { kind: "error" | "success"; message: string; onDismiss?: () => void }) { return <p role={kind === "error" ? "alert" : "status"} className={`banner ${kind}`}>{message}{onDismiss && <button onClick={onDismiss}>Dismiss</button>}</p>; }
function EmptyState({ title, text, action, onAction }: { title: string; text: string; action?: string; onAction?: () => void }) { return <div className="empty-state"><h3>{title}</h3><p>{text}</p>{action && <button className="primary" onClick={onAction}>{action}</button>}</div>; }
function EmptyDashboard({ role }: { role: Role }) { return <div className="empty-state"><h1>My courses</h1><p>{role === "staff" ? "Create your first course to start a course forum." : "You have not been added to a course yet. Ask your course staff to add your existing username."}</p></div>; }
createRoot(document.getElementById("root")!).render(<StrictMode><App /></StrictMode>);
